const colors = { off: '#ffffff', heating: '#e24d42', cooling: '#5794f2', Low: '#b877d9', Normal: '#73bf69', High: '#f2cc0c', 'Setpoint unavailable': '#8e8e8e' };
const temperaturePoints = [];
const humiditySeries = [];
let unit = 'F';

for (const frame of context.panel.data.series) {
  const timeField = frame.fields.find((field) => field.type === 'time');
  const valueField = frame.fields.find((field) => field.type === 'number');
  if (!timeField || !valueField) continue;

  const times = timeField.values.buffer || timeField.values;
  const values = valueField.values.buffer || valueField.values;
  const labels = valueField.labels || {};
  if (labels.unit) unit = labels.unit;

  if (labels.state !== undefined) {
    const state = labels.state;
    humiditySeries.push({
      name: state,
      type: 'line',
      yAxisIndex: 1,
      showSymbol: false,
      connectNulls: false,
      lineStyle: { color: colors[state] || '#8e8e8e', width: 2 },
      itemStyle: { color: colors[state] || '#8e8e8e' },
      data: Array.from(values, (value, index) => [times[index], value == null ? null : Number(value)])
    });
    continue;
  }

  const equipment = labels.equipment || 'off';
  for (let index = 0; index < values.length; index += 1) {
    if (values[index] == null) continue;
    const time = Number(times[index]);
    const value = Number(values[index]);
    if (Number.isFinite(time) && Number.isFinite(value)) temperaturePoints.push({ time, value, equipment });
  }
}

temperaturePoints.sort((left, right) => left.time - right.time);
const segments = { off: [], heating: [], cooling: [] };
for (let index = 1; index < temperaturePoints.length; index += 1) {
  const start = temperaturePoints[index - 1];
  const end = temperaturePoints[index];
  if (end.time <= start.time || end.time - start.time > 120000) continue;
  if (segments[end.equipment]) segments[end.equipment].push([start.time, start.value, end.time, end.value]);
}

const temperatureSeries = Object.entries(segments).map(([equipment, data]) => ({
  name: equipment,
  type: 'custom',
  coordinateSystem: 'cartesian2d',
  yAxisIndex: 0,
  clip: true,
  lineStyle: { color: colors[equipment], width: 2 },
  itemStyle: { color: colors[equipment] },
  dimensions: ['startTime', 'startTemperature', 'endTime', 'endTemperature'],
  encode: { x: [0, 2], y: [1, 3], tooltip: [0, 1, 2, 3] },
  data,
  renderItem: (params, api) => {
    const start = api.coord([api.value(0), api.value(1)]);
    const end = api.coord([api.value(2), api.value(3)]);
    return { type: 'line', shape: { x1: start[0], y1: start[1], x2: end[0], y2: end[1] }, style: { stroke: colors[equipment], lineWidth: 2 } };
  }
}));

return {
  backgroundColor: 'transparent',
  animation: false,
  grid: { left: 65, right: 70, top: 35, bottom: 55, containLabel: true },
  tooltip: { trigger: 'axis', axisPointer: { type: 'cross' } },
  color: ['#ffffff', '#e24d42', '#5794f2', '#b877d9', '#73bf69', '#f2cc0c', '#8e8e8e'],
  legend: { bottom: 0, data: [...Object.keys(segments), ...new Set(humiditySeries.map((item) => item.name))], textStyle: { color: 'rgba(128, 128, 128, .9)' } },
  xAxis: { type: 'time', boundaryGap: false },
  yAxis: [
    { type: 'value', name: 'Temperature (' + unit + ')', position: 'left', scale: true, minInterval: 0.5, axisLabel: { formatter: (value) => Number(value).toFixed(1) }, splitLine: { lineStyle: { color: 'rgba(128, 128, 128, .18)' } } },
    { type: 'value', name: 'Humidity (%)', position: 'right', scale: true, minInterval: 0.5, axisLabel: { formatter: (value) => Number(value).toFixed(1) + '%' }, splitLine: { show: false } }
  ],
  series: [...temperatureSeries, ...humiditySeries]
};
